    /** Boxes for {@code style} in {@code state}: {@code {x1, y1, z1, x2, y2, z2}} in model units. */
    public static double[][] boxes(ConsoleStyle style, ConsoleState state) {
        return switch (style) {
            case CLASSIC -> switch (state) {
                case OFF -> CLASSIC_OFF;
                case STANDBY -> CLASSIC_OFF;
                case RUNNING -> CLASSIC_RUNNING;
            };
            case COMPACT -> switch (state) {
                case OFF -> COMPACT_OFF;
                case STANDBY -> COMPACT_OFF;
                case RUNNING -> COMPACT_RUNNING;
            };
            case HIFI -> switch (state) {
                case OFF -> HIFI_OFF;
                case STANDBY -> HIFI_OFF;
                case RUNNING -> HIFI_RUNNING;
            };
            case LEGACY -> switch (state) {
                case OFF -> LEGACY_OFF;
                case STANDBY -> LEGACY_OFF;
                case RUNNING -> LEGACY_OFF;
            };
            case FULLBLOCK -> switch (state) {
                case OFF -> FULLBLOCK_OFF;
                case STANDBY -> FULLBLOCK_OFF;
                case RUNNING -> FULLBLOCK_OFF;
            };
        };
    }

